1720	int opentelemetry_prot_uncompress(struct mk_http_session *session,
1721	                                  struct mk_http_request *request,
1722	                                  char **output_buffer,
1723	                                  size_t *output_size)
1724	{
1725	    struct mk_http_header *header;
1726	    size_t                 index;
1727	
1728	    *output_buffer = NULL;
1729	    *output_size = 0;
1730	
1731	    for (index = 0;
1732	         index < session->parser.headers_extra_count;
1733	         index++) {
1734	        header = &session->parser.headers_extra[index];
1735	
1736	        if (strncasecmp(header->key.data, "Content-Encoding", 16) == 0) {
1737	            if (strncasecmp(header->val.data, "gzip", 4) == 0) {
1738	                return uncompress_gzip(output_buffer,
1739	                                       output_size,
1740	                                       request->data.data,
1741	                                       request->data.len);
1742	            }
1743	            else if (strncasecmp(header->val.data, "zlib", 4) == 0) {
1744	                return uncompress_zlib(output_buffer,
1745	                                       output_size,
1746	                                       request->data.data,
1747	                                       request->data.len);
1748	            }
1749	            else if (strncasecmp(header->val.data, "zstd", 4) == 0) {
1750	                return uncompress_zstd(output_buffer,
1751	                                       output_size,
1752	                                       request->data.data,
1753	                                       request->data.len);
1754	            }
1755	            else if (strncasecmp(header->val.data, "snappy", 6) == 0) {
1756	                return uncompress_snappy(output_buffer,
1757	                                         output_size,
1758	                                         request->data.data,
1759	                                         request->data.len);
1760	            }
1761	            else if (strncasecmp(header->val.data, "deflate", 4) == 0) {
1762	                return uncompress_deflate(output_buffer,
1763	                                          output_size,
1764	                                          request->data.data,
1765	                                          request->data.len);
1766	            }
1767	            else {
1768	                return -2;
1769	            }
1770	        }
1771	    }
1772	
1773	    return 0;
1774	}
