1778	 * Handle an incoming request. It performs extra checks over the request, if
1779	 * everything is OK, it enqueue the incoming payload.
1780	 */
1781	int opentelemetry_prot_handle(struct flb_opentelemetry *ctx, struct http_conn *conn,
1782	                              struct mk_http_session *session,
1783	                              struct mk_http_request *request)
1784	{
1785	    int i;
1786	    int ret = -1;
1787	    int len;
1788	    char *uri;
1789	    char *qs;
1790	    char *out_chunked = NULL;
1791	    size_t out_chunked_size = 0;
1792	    off_t diff;
1793	    size_t tag_len;
1794	    flb_sds_t tag;
1795	    char *original_data = NULL;
1796	    size_t original_data_size;
1797	    char *uncompressed_data = NULL;
1798	    size_t uncompressed_data_size;
1799	    struct mk_http_header *header;
1800	
1801	    if (request->uri.data[0] != '/') {
1802	        send_response(conn, 400, "error: invalid request\n");
1803	        return -1;
1804	    }
1805	
1806	    /* Decode URI */
1807	    uri = mk_utils_url_decode(request->uri);
1808	    if (!uri) {
1809	        uri = mk_mem_alloc_z(request->uri.len + 1);
1810	        if (!uri) {
1811	            return -1;
1812	        }
1813	        memcpy(uri, request->uri.data, request->uri.len);
1814	        uri[request->uri.len] = '\0';
1815	    }
1816	
1817	    if (strcmp(uri, "/v1/metrics") != 0 &&
1818	        strcmp(uri, "/v1/traces") != 0  &&
1819	        strcmp(uri, "/v1/logs") != 0) {
1820	
1821	        send_response(conn, 400, "error: invalid endpoint\n");
1822	        mk_mem_free(uri);
1823	
1824	        return -1;
1825	    }
1826	
1827	    /* Try to match a query string, so we can remove it */
1828	    qs = strchr(uri, '?');
1829	    if (qs) {
1830	        /* remove the query string part */
1831	        diff = qs - uri;
1832	        uri[diff] = '\0';
1833	    }
1834	
1835	    /* Compose the query string using the URI */
1836	    len = strlen(uri);
1837	
1838	    if (ctx->tag_from_uri != FLB_TRUE) {
1839	        tag = flb_sds_create(ctx->ins->tag);
1840	    }
1841	    else {
1842	        tag = flb_sds_create_size(len);
1843	        if (!tag) {
1844	            mk_mem_free(uri);
1845	            return -1;
1846	        }
1847	
1848	        /* New tag skipping the URI '/' */
1849	        flb_sds_cat(tag, uri + 1, len - 1);
1850	
1851	        /* Sanitize, only allow alphanum chars */
1852	        for (i = 0; i < flb_sds_len(tag); i++) {
1853	            if (!isalnum(tag[i]) && tag[i] != '_' && tag[i] != '.') {
1854	                tag[i] = '_';
1855	            }
1856	        }
1857	    }
1858	
1859	    tag_len = flb_sds_len(tag);
1860	
1861	    /* Check if we have a Host header: Hostname ; port */
1862	    mk_http_point_header(&request->host, &session->parser, MK_HEADER_HOST);
1863	
1864	    /* Header: Connection */
1865	    mk_http_point_header(&request->connection, &session->parser,
1866	                         MK_HEADER_CONNECTION);
1867	
1868	    /* HTTP/1.1 needs Host header */
1869	    if (!request->host.data && request->protocol == MK_HTTP_PROTOCOL_11) {
1870	        flb_sds_destroy(tag);
1871	        mk_mem_free(uri);
1872	        return -1;
1873	    }
1874	
1875	    /* Should we close the session after this request ? */
1876	    mk_http_keepalive_check(session, request, ctx->server);
1877	
1878	    /* Content Length */
1879	    header = &session->parser.headers[MK_HEADER_CONTENT_LENGTH];
1880	    if (header->type == MK_HEADER_CONTENT_LENGTH) {
1881	        request->_content_length.data = header->val.data;
1882	        request->_content_length.len  = header->val.len;
1883	    }
1884	    else {
1885	        request->_content_length.data = NULL;
1886	    }
1887	
1888	    mk_http_point_header(&request->content_type, &session->parser, MK_HEADER_CONTENT_TYPE);
1889	
1890	    if (request->method != MK_METHOD_POST) {
1891	        flb_sds_destroy(tag);
1892	        mk_mem_free(uri);
1893	        send_response(conn, 400, "error: invalid HTTP method\n");
1894	        return -1;
1895	    }
1896	
1897	    original_data = request->data.data;
1898	    original_data_size = request->data.len;
1899	
1900	    /* check if the request comes with chunked transfer encoding */
1901	    if (mk_http_parser_is_content_chunked(&session->parser)) {
1902	        out_chunked = NULL;
1903	        out_chunked_size = 0;
1904	
1905	        /* decode the chunks */
1906	        ret = mk_http_parser_chunked_decode(&session->parser,
1907	                                            conn->buf_data,
1908	                                            conn->buf_len,
1909	                                            &out_chunked,
1910	                                            &out_chunked_size);
