    result = flb_log_event_encoder_append_metadata_values(
                encoder,
                FLB_LOG_EVENT_STRING_VALUE("schema", 6),
                FLB_LOG_EVENT_STRING_VALUE("otlp", 4),
                FLB_LOG_EVENT_STRING_VALUE("resource_id", 11),
